def solve_a_n(N):
    a = {1: 0}
    for n in range(2, N + 1):
        max_val = -1
        for i in range(1, n):
            # a_i + a_{n-i} + min(i, n-i)
            current_val = a[i] + a[n - i] + min(i, n - i)
            if current_val > max_val:
                max_val = current_val
        a[n] = max_val
    return a

results = solve_a_n(10)
print({k: v for k, v in results.items()})

def calculate_a(n, memo):
    if n in memo:
        return memo[n]
    if n == 1:
        return 0

    if n % 2 == 0:
        # n = 2k, k = n/2
        k = n // 2
        result = 2 * calculate_a(k, memo) + k
    else:
        # n = 2k+1, k = (n-1)/2
        k = (n - 1) // 2
        result = calculate_a(k, memo) + calculate_a(k + 1, memo) + k

    memo[n] = result
    return result

