def calculate_a(n):
    if n == 1:
        return 0

    # Memoization dictionary to store already calculated values
    memo = {1: 0}

    def solve(n):
        if n in memo:
            return memo[n]

        if n % 2 == 0:
            # n = 2k => k = n/2
            k = n // 2
            # a_{2k} = 2a_k + k
            result = 2 * solve(k) + k
        else:
            # n = 2k+1 => k = (n-1)/2
            k = (n - 1) // 2
            # a_{2k+1} = a_k + a_{k+1} + k
            result = solve(k) + solve(k + 1) + k

        memo[n] = result
        return result

    return solve(n)

target_n = 2025
a_2025 = calculate_a(target_n)
print(f"a_{target_n} = {a_2025}")
